    52→/// The strategy to be used when validating the block's signatures.
    53→#[cfg_attr(feature = "arbitrary-fuzz", derive(Arbitrary))]
    54→#[derive(PartialEq, Clone, Copy, Debug)]
    55→pub enum BlockSignatureStrategy {
    56→    /// Do not validate any signature. Use with caution.
    57→    NoVerification,
    58→    /// Validate each signature individually, as its object is being processed.
    59→    VerifyIndividual,
    60→    /// Validate only the randao reveal signature.
    61→    VerifyRandao,
    62→    /// Verify all signatures in bulk at the beginning of block processing.
    63→    VerifyBulk,
    64→}
    65→
    66→/// The strategy to be used when validating the block's signatures.
    67→#[cfg_attr(feature = "arbitrary-fuzz", derive(Arbitrary))]
    68→#[derive(PartialEq, Clone, Copy)]
    69→pub enum VerifySignatures {
    70→    /// Validate all signatures encountered.
    71→    True,
    72→    /// Do not validate any signature. Use with caution.
    73→    False,
    74→}
    75→
    76→impl VerifySignatures {
    77→    pub fn is_true(self) -> bool {
    78→        self == VerifySignatures::True
    79→    }
    80→}
