    82→/// Control verification of the latest block header.
    83→#[cfg_attr(feature = "arbitrary-fuzz", derive(Arbitrary))]
    84→#[derive(PartialEq, Clone, Copy)]
    85→pub enum VerifyBlockRoot {
    86→    True,
    87→    False,
    88→}
