    90→/// Updates the state for a new block, whilst validating that the block is valid, optionally
    91→/// checking the block proposer signature.
    92→///
    93→/// Returns `Ok(())` if the block is valid and the state was successfully updated. Otherwise
    94→/// returns an error describing why the block was invalid or how the function failed to execute.
    95→///
    96→/// If `block_root` is `Some`, this root is used for verification of the proposer's signature. If it
    97→/// is `None` the signing root is computed from scratch. This parameter only exists to avoid
    98→/// re-calculating the root when it is already known. Note `block_root` should be equal to the
    99→/// tree hash root of the block, NOT the signing root of the block. This function takes
   100→/// care of mixing in the domain.
   101→#[instrument(skip_all)]
   102→pub fn per_block_processing<E: EthSpec, Payload: AbstractExecPayload<E>>(
   103→    state: &mut BeaconState<E>,
   104→    signed_block: &SignedBeaconBlock<E, Payload>,
   105→    block_signature_strategy: BlockSignatureStrategy,
   106→    verify_block_root: VerifyBlockRoot,
   107→    ctxt: &mut ConsensusContext<E>,
   108→    spec: &ChainSpec,
   109→) -> Result<(), BlockProcessingError> {
   110→    let block = signed_block.message();
   111→
   112→    // Verify that the `SignedBeaconBlock` instantiation matches the fork at `signed_block.slot()`.
   113→    signed_block
   114→        .fork_name(spec)
   115→        .map_err(BlockProcessingError::InconsistentBlockFork)?;
   116→
   117→    // Verify that the `BeaconState` instantiation matches the fork at `state.slot()`.
   118→    state
   119→        .fork_name(spec)
   120→        .map_err(BlockProcessingError::InconsistentStateFork)?;
   121→
   122→    // Build epoch cache if it hasn't already been built, or if it is no longer valid
   123→    initialize_epoch_cache(state, spec)?;
   124→    initialize_progressive_balances_cache(state, spec)?;
   125→    state.build_slashings_cache()?;
   126→
   127→    let verify_signatures = match block_signature_strategy {
   128→        BlockSignatureStrategy::VerifyBulk => {
   129→            // Verify all signatures in the block at once.
   130→            block_verify!(
   131→                BlockSignatureVerifier::verify_entire_block(
   132→                    state,
   133→                    |i| get_pubkey_from_state(state, i),
   134→                    |pk_bytes| pk_bytes.decompress().ok().map(Cow::Owned),
   135→                    signed_block,
   136→                    ctxt,
   137→                    spec
   138→                )
   139→                .is_ok(),
   140→                BlockProcessingError::BulkSignatureVerificationFailed
   141→            );
   142→            VerifySignatures::False
   143→        }
   144→        BlockSignatureStrategy::VerifyIndividual => VerifySignatures::True,
   145→        BlockSignatureStrategy::NoVerification => VerifySignatures::False,
   146→        BlockSignatureStrategy::VerifyRandao => VerifySignatures::False,
   147→    };
   148→
   149→    let proposer_index = process_block_header(
   150→        state,
   151→        block.temporary_block_header(),
   152→        verify_block_root,
   153→        ctxt,
   154→        spec,
   155→    )?;
   156→
   157→    if verify_signatures.is_true() {
   158→        verify_block_signature(state, signed_block, ctxt, spec)?;
   159→    }
   160→
   161→    let verify_randao = if let BlockSignatureStrategy::VerifyRandao = block_signature_strategy {
   162→        VerifySignatures::True
   163→    } else {
   164→        verify_signatures
   165→    };
   166→    // Ensure the current and previous epoch committee caches are built.
   167→    state.build_committee_cache(RelativeEpoch::Previous, spec)?;
   168→    state.build_committee_cache(RelativeEpoch::Current, spec)?;
   169→
   170→    // The call to the `process_execution_payload` must happen before the call to the
   171→    // `process_randao` as the former depends on the `randao_mix` computed with the reveal of the
   172→    // previous block.
   173→    if is_execution_enabled(state, block.body()) {
   174→        let body = block.body();
   175→        process_withdrawals::<E, Payload>(state, body.execution_payload()?, spec)?;
   176→        process_execution_payload::<E, Payload>(state, body, spec)?;
   177→    }
   178→
   179→    process_randao(state, block, verify_randao, ctxt, spec)?;
   180→    process_eth1_data(state, block.body().eth1_data())?;
   181→    process_operations(state, block.body(), verify_signatures, ctxt, spec)?;
   182→
   183→    if let Ok(sync_aggregate) = block.body().sync_aggregate() {
   184→        process_sync_aggregate(
   185→            state,
   186→            sync_aggregate,
   187→            proposer_index,
   188→            verify_signatures,
   189→            spec,
   190→        )?;
   191→    }
   192→
   193→    if is_progressive_balances_enabled(state) {
   194→        update_progressive_balances_metrics(state.progressive_balances_cache())?;
   195→    }
   196→
   197→    Ok(())
   198→}
