   317→/// Update the `state.eth1_data_votes` based upon the `eth1_data` provided.
   318→pub fn process_eth1_data<E: EthSpec>(
   319→    state: &mut BeaconState<E>,
   320→    eth1_data: &Eth1Data,
   321→) -> Result<(), Error> {
   322→    if let Some(new_eth1_data) = get_new_eth1_data(state, eth1_data)? {
   323→        *state.eth1_data_mut() = new_eth1_data;
   324→    }
   325→
   326→    state.eth1_data_votes_mut().push(eth1_data.clone())?;
   327→
   328→    Ok(())
   329→}
   330→
   331→/// Returns `Ok(Some(eth1_data))` if adding the given `eth1_data` to `state.eth1_data_votes` would
   332→/// result in a change to `state.eth1_data`.
   333→pub fn get_new_eth1_data<E: EthSpec>(
   334→    state: &BeaconState<E>,
   335→    eth1_data: &Eth1Data,
   336→) -> Result<Option<Eth1Data>, ArithError> {
   337→    let num_votes = state
   338→        .eth1_data_votes()
   339→        .iter()
   340→        .filter(|vote| *vote == eth1_data)
   341→        .count();
   342→
   343→    // The +1 is to account for the `eth1_data` supplied to the function.
   344→    if num_votes.safe_add(1)?.safe_mul(2)? > E::SlotsPerEth1VotingPeriod::to_usize() {
   345→        Ok(Some(eth1_data.clone()))
   346→    } else {
   347→        Ok(None)
   348→    }
   349→}
