   351→/// Performs *partial* verification of the `payload`.
   352→///
   353→/// The verification is partial, since the execution payload is not verified against an execution
   354→/// engine. That is expected to be performed by an upstream function.
   355→///
   356→/// ## Specification
   357→///
   358→/// Contains a partial set of checks from the `process_execution_payload` function:
   359→///
   360→/// https://github.com/ethereum/consensus-specs/blob/v1.1.5/specs/merge/beacon-chain.md#process_execution_payload
   361→pub fn partially_verify_execution_payload<E: EthSpec, Payload: AbstractExecPayload<E>>(
   362→    state: &BeaconState<E>,
   363→    block_slot: Slot,
   364→    body: BeaconBlockBodyRef<E, Payload>,
   365→    spec: &ChainSpec,
   366→) -> Result<(), BlockProcessingError> {
   367→    let payload = body.execution_payload()?;
   368→    if is_merge_transition_complete(state) {
   369→        block_verify!(
   370→            payload.parent_hash() == state.latest_execution_payload_header()?.block_hash(),
   371→            BlockProcessingError::ExecutionHashChainIncontiguous {
   372→                expected: state.latest_execution_payload_header()?.block_hash(),
   373→                found: payload.parent_hash(),
   374→            }
   375→        );
   376→    }
   377→    block_verify!(
   378→        payload.prev_randao() == *state.get_randao_mix(state.current_epoch())?,
   379→        BlockProcessingError::ExecutionRandaoMismatch {
   380→            expected: *state.get_randao_mix(state.current_epoch())?,
   381→            found: payload.prev_randao(),
   382→        }
   383→    );
   384→
   385→    let timestamp = compute_timestamp_at_slot(state, block_slot, spec)?;
   386→    block_verify!(
   387→        payload.timestamp() == timestamp,
   388→        BlockProcessingError::ExecutionInvalidTimestamp {
   389→            expected: timestamp,
   390→            found: payload.timestamp(),
   391→        }
   392→    );
   393→
   394→    if let Ok(blob_commitments) = body.blob_kzg_commitments() {
   395→        // Verify commitments are under the limit.
   396→        let max_blobs_per_block =
   397→            spec.max_blobs_per_block(block_slot.epoch(E::slots_per_epoch())) as usize;
   398→        block_verify!(
   399→            blob_commitments.len() <= max_blobs_per_block,
   400→            BlockProcessingError::ExecutionInvalidBlobsLen {
   401→                max: max_blobs_per_block,
   402→                actual: blob_commitments.len(),
   403→            }
   404→        );
   405→    }
   406→
   407→    Ok(())
   408→}
