   410→/// Calls `partially_verify_execution_payload` and then updates the payload header in the `state`.
   411→///
   412→/// ## Specification
   413→///
   414→/// Partially equivalent to the `process_execution_payload` function:
   415→///
   416→/// https://github.com/ethereum/consensus-specs/blob/v1.1.5/specs/merge/beacon-chain.md#process_execution_payload
   417→pub fn process_execution_payload<E: EthSpec, Payload: AbstractExecPayload<E>>(
   418→    state: &mut BeaconState<E>,
   419→    body: BeaconBlockBodyRef<E, Payload>,
   420→    spec: &ChainSpec,
   421→) -> Result<(), BlockProcessingError> {
   422→    partially_verify_execution_payload::<E, Payload>(state, state.slot(), body, spec)?;
   423→    let payload = body.execution_payload()?;
   424→    match state.latest_execution_payload_header_mut()? {
   425→        ExecutionPayloadHeaderRefMut::Bellatrix(header_mut) => {
   426→            match payload.to_execution_payload_header() {
   427→                ExecutionPayloadHeader::Bellatrix(header) => *header_mut = header,
   428→                _ => return Err(BlockProcessingError::IncorrectStateType),
   429→            }
   430→        }
   431→        ExecutionPayloadHeaderRefMut::Capella(header_mut) => {
   432→            match payload.to_execution_payload_header() {
   433→                ExecutionPayloadHeader::Capella(header) => *header_mut = header,
   434→                _ => return Err(BlockProcessingError::IncorrectStateType),
   435→            }
   436→        }
   437→        ExecutionPayloadHeaderRefMut::Deneb(header_mut) => {
   438→            match payload.to_execution_payload_header() {
   439→                ExecutionPayloadHeader::Deneb(header) => *header_mut = header,
   440→                _ => return Err(BlockProcessingError::IncorrectStateType),
   441→            }
   442→        }
   443→        ExecutionPayloadHeaderRefMut::Electra(header_mut) => {
   444→            match payload.to_execution_payload_header() {
   445→                ExecutionPayloadHeader::Electra(header) => *header_mut = header,
   446→                _ => return Err(BlockProcessingError::IncorrectStateType),
   447→            }
   448→        }
   449→        ExecutionPayloadHeaderRefMut::Fulu(header_mut) => {
   450→            match payload.to_execution_payload_header() {
   451→                ExecutionPayloadHeader::Fulu(header) => *header_mut = header,
   452→                _ => return Err(BlockProcessingError::IncorrectStateType),
   453→            }
   454→        }
   455→        ExecutionPayloadHeaderRefMut::Gloas(header_mut) => {
   456→            match payload.to_execution_payload_header() {
   457→                ExecutionPayloadHeader::Gloas(header) => *header_mut = header,
   458→                _ => return Err(BlockProcessingError::IncorrectStateType),
   459→            }
   460→        }
   461→    }
   462→
   463→    Ok(())
   464→}
   465→
   466→/// These functions will definitely be called before the merge. Their entire purpose is to check if
   467→/// the merge has happened or if we're on the transition block. Thus we don't want to propagate
   468→/// errors from the `BeaconState` being an earlier variant than `BeaconStateBellatrix` as we'd have to
   469→/// repeatedly write code to treat these errors as false.
   470→/// https://github.com/ethereum/consensus-specs/blob/dev/specs/bellatrix/beacon-chain.md#is_merge_transition_complete
   471→pub fn is_merge_transition_complete<E: EthSpec>(state: &BeaconState<E>) -> bool {
   472→    if state.fork_name_unchecked().capella_enabled() {
   473→        true
   474→    } else if state.fork_name_unchecked().bellatrix_enabled() {
   475→        // We must check defaultness against the payload header with 0x0 roots, as that's what's meant
   476→        // by `ExecutionPayloadHeader()` in the spec.
   477→        state
   478→            .latest_execution_payload_header()
   479→            .map(|header| !header.is_default_with_zero_roots())
   480→            .unwrap_or(false)
   481→    } else {
   482→        false
   483→    }
   484→}
   485→/// https://github.com/ethereum/consensus-specs/blob/dev/specs/bellatrix/beacon-chain.md#is_merge_transition_block
   486→pub fn is_merge_transition_block<E: EthSpec, Payload: AbstractExecPayload<E>>(
   487→    state: &BeaconState<E>,
   488→    body: BeaconBlockBodyRef<E, Payload>,
   489→) -> bool {
   490→    // For execution payloads in blocks (which may be headers) we must check defaultness against
   491→    // the payload with `transactions_root` equal to the tree hash of the empty list.
   492→    body.execution_payload()
   493→        .map(|payload| {
   494→            !is_merge_transition_complete(state) && !payload.is_default_with_empty_roots()
   495→        })
   496→        .unwrap_or(false)
   497→}
   498→/// https://github.com/ethereum/consensus-specs/blob/dev/specs/bellatrix/beacon-chain.md#is_execution_enabled
   499→pub fn is_execution_enabled<E: EthSpec, Payload: AbstractExecPayload<E>>(
   500→    state: &BeaconState<E>,
   501→    body: BeaconBlockBodyRef<E, Payload>,
   502→) -> bool {
   503→    is_merge_transition_block(state, body) || is_merge_transition_complete(state)
   504→}
   505→
   506→/// https://github.com/ethereum/consensus-specs/blob/dev/specs/bellatrix/beacon-chain.md#compute_timestamp_at_slot
   507→pub fn compute_timestamp_at_slot<E: EthSpec>(
   508→    state: &BeaconState<E>,
   509→    block_slot: Slot,
   510→    spec: &ChainSpec,
   511→) -> Result<u64, ArithError> {
   512→    let slots_since_genesis = block_slot.as_u64().safe_sub(spec.genesis_slot.as_u64())?;
   513→    slots_since_genesis
   514→        .safe_mul(spec.seconds_per_slot)
   515→        .and_then(|since_genesis| state.genesis_time().safe_add(since_genesis))
   516→}
   517→
   518→/// Compute the next batch of withdrawals which should be included in a block.
   519→///
   520→/// https://github.com/ethereum/consensus-specs/blob/dev/specs/electra/beacon-chain.md#new-get_expected_withdrawals
   521→pub fn get_expected_withdrawals<E: EthSpec>(
   522→    state: &BeaconState<E>,
   523→    spec: &ChainSpec,
   524→) -> Result<(Withdrawals<E>, Option<usize>), BlockProcessingError> {
   525→    let epoch = state.current_epoch();
   526→    let mut withdrawal_index = state.next_withdrawal_index()?;
   527→    let mut validator_index = state.next_withdrawal_validator_index()?;
   528→    let mut withdrawals = Vec::<Withdrawal>::with_capacity(E::max_withdrawals_per_payload());
   529→    let fork_name = state.fork_name_unchecked();
   530→
   531→    // [New in Electra:EIP7251]
   532→    // Consume pending partial withdrawals
   533→    let processed_partial_withdrawals_count =
   534→        if let Ok(pending_partial_withdrawals) = state.pending_partial_withdrawals() {
   535→            let mut processed_partial_withdrawals_count = 0;
   536→            for withdrawal in pending_partial_withdrawals {
   537→                if withdrawal.withdrawable_epoch > epoch
   538→                    || withdrawals.len() == spec.max_pending_partials_per_withdrawals_sweep as usize
   539→                {
   540→                    break;
   541→                }
   542→
   543→                let validator = state.get_validator(withdrawal.validator_index as usize)?;
   544→
   545→                let has_sufficient_effective_balance =
   546→                    validator.effective_balance >= spec.min_activation_balance;
   547→                let total_withdrawn = withdrawals
   548→                    .iter()
   549→                    .filter_map(|w| {
   550→                        (w.validator_index == withdrawal.validator_index).then_some(w.amount)
   551→                    })
   552→                    .safe_sum()?;
   553→                let balance = state
   554→                    .get_balance(withdrawal.validator_index as usize)?
   555→                    .safe_sub(total_withdrawn)?;
   556→                let has_excess_balance = balance > spec.min_activation_balance;
   557→
   558→                if validator.exit_epoch == spec.far_future_epoch
   559→                    && has_sufficient_effective_balance
   560→                    && has_excess_balance
   561→                {
   562→                    let withdrawable_balance = std::cmp::min(
   563→                        balance.safe_sub(spec.min_activation_balance)?,
   564→                        withdrawal.amount,
   565→                    );
   566→                    withdrawals.push(Withdrawal {
   567→                        index: withdrawal_index,
   568→                        validator_index: withdrawal.validator_index,
   569→                        address: validator
   570→                            .get_execution_withdrawal_address(spec)
   571→                            .ok_or(BeaconStateError::NonExecutionAddressWithdrawalCredential)?,
   572→                        amount: withdrawable_balance,
   573→                    });
   574→                    withdrawal_index.safe_add_assign(1)?;
   575→                }
   576→                processed_partial_withdrawals_count.safe_add_assign(1)?;
   577→            }
   578→            Some(processed_partial_withdrawals_count)
   579→        } else {
   580→            None
   581→        };
   582→
   583→    let bound = std::cmp::min(
   584→        state.validators().len() as u64,
   585→        spec.max_validators_per_withdrawals_sweep,
   586→    );
   587→    for _ in 0..bound {
   588→        let validator = state.get_validator(validator_index as usize)?;
   589→        let partially_withdrawn_balance = withdrawals
   590→            .iter()
   591→            .filter_map(|withdrawal| {
   592→                (withdrawal.validator_index == validator_index).then_some(withdrawal.amount)
   593→            })
   594→            .safe_sum()?;
   595→        let balance = state
   596→            .balances()
   597→            .get(validator_index as usize)
   598→            .ok_or(BeaconStateError::BalancesOutOfBounds(
   599→                validator_index as usize,
   600→            ))?
   601→            .safe_sub(partially_withdrawn_balance)?;
   602→        if validator.is_fully_withdrawable_validator(balance, epoch, spec, fork_name) {
   603→            withdrawals.push(Withdrawal {
   604→                index: withdrawal_index,
   605→                validator_index,
   606→                address: validator
   607→                    .get_execution_withdrawal_address(spec)
   608→                    .ok_or(BlockProcessingError::WithdrawalCredentialsInvalid)?,
   609→                amount: balance,
   610→            });
   611→            withdrawal_index.safe_add_assign(1)?;
   612→        } else if validator.is_partially_withdrawable_validator(balance, spec, fork_name) {
   613→            withdrawals.push(Withdrawal {
   614→                index: withdrawal_index,
   615→                validator_index,
   616→                address: validator
   617→                    .get_execution_withdrawal_address(spec)
   618→                    .ok_or(BlockProcessingError::WithdrawalCredentialsInvalid)?,
   619→                amount: balance.safe_sub(validator.get_max_effective_balance(spec, fork_name))?,
   620→            });
   621→            withdrawal_index.safe_add_assign(1)?;
   622→        }
   623→        if withdrawals.len() == E::max_withdrawals_per_payload() {
   624→            break;
   625→        }
   626→        validator_index = validator_index
   627→            .safe_add(1)?
   628→            .safe_rem(state.validators().len() as u64)?;
   629→    }
   630→
   631→    Ok((withdrawals.into(), processed_partial_withdrawals_count))
   632→}
   633→
   634→/// Apply withdrawals to the state.
   635→pub fn process_withdrawals<E: EthSpec, Payload: AbstractExecPayload<E>>(
   636→    state: &mut BeaconState<E>,
   637→    payload: Payload::Ref<'_>,
   638→    spec: &ChainSpec,
   639→) -> Result<(), BlockProcessingError> {
   640→    if state.fork_name_unchecked().capella_enabled() {
   641→        let (expected_withdrawals, processed_partial_withdrawals_count) =
   642→            get_expected_withdrawals(state, spec)?;
   643→        let expected_root = expected_withdrawals.tree_hash_root();
   644→        let withdrawals_root = payload.withdrawals_root()?;
   645→
   646→        if expected_root != withdrawals_root {
   647→            return Err(BlockProcessingError::WithdrawalsRootMismatch {
   648→                expected: expected_root,
   649→                found: withdrawals_root,
   650→            });
   651→        }
   652→
   653→        for withdrawal in expected_withdrawals.iter() {
   654→            decrease_balance(
   655→                state,
   656→                withdrawal.validator_index as usize,
   657→                withdrawal.amount,
   658→            )?;
   659→        }
   660→
   661→        // Update pending partial withdrawals [New in Electra:EIP7251]
   662→        if let Some(processed_partial_withdrawals_count) = processed_partial_withdrawals_count {
   663→            state
   664→                .pending_partial_withdrawals_mut()?
   665→                .pop_front(processed_partial_withdrawals_count)?;
   666→        }
   667→
   668→        // Update the next withdrawal index if this block contained withdrawals
   669→        if let Some(latest_withdrawal) = expected_withdrawals.last() {
   670→            *state.next_withdrawal_index_mut()? = latest_withdrawal.index.safe_add(1)?;
   671→
   672→            // Update the next validator index to start the next withdrawal sweep
   673→            if expected_withdrawals.len() == E::max_withdrawals_per_payload() {
   674→                // Next sweep starts after the latest withdrawal's validator index
   675→                let next_validator_index = latest_withdrawal
   676→                    .validator_index
   677→                    .safe_add(1)?
   678→                    .safe_rem(state.validators().len() as u64)?;
   679→                *state.next_withdrawal_validator_index_mut()? = next_validator_index;
   680→            }
   681→        }
   682→
   683→        // Advance sweep by the max length of the sweep if there was not a full set of withdrawals
   684→        if expected_withdrawals.len() != E::max_withdrawals_per_payload() {
   685→            let next_validator_index = state
   686→                .next_withdrawal_validator_index()?
   687→                .safe_add(spec.max_validators_per_withdrawals_sweep)?
   688→                .safe_rem(state.validators().len() as u64)?;
   689→            *state.next_withdrawal_validator_index_mut()? = next_validator_index;
   690→        }
   691→
   692→        Ok(())
   693→    } else {
   694→        // these shouldn't even be encountered but they're here for completeness
   695→        Ok(())
   696→    }
   697→}
   698→

