     5→#[derive(Debug)]
     6→pub enum Error {
     7→    DecodingTransaction(String),
     8→    LengthMismatch { expected: usize, found: usize },
     9→    VersionHashMismatch { expected: Hash256, found: Hash256 },
    10→}
    11→
    12→pub fn verify_versioned_hashes<E: EthSpec>(
    13→    execution_payload: ExecutionPayloadRef<E>,
    14→    expected_versioned_hashes: &[VersionedHash],
    15→) -> Result<(), Error> {
    16→    let versioned_hashes =
    17→        extract_versioned_hashes_from_transactions::<E>(execution_payload.transactions())?;
    18→    if versioned_hashes.len() != expected_versioned_hashes.len() {
    19→        return Err(Error::LengthMismatch {
    20→            expected: expected_versioned_hashes.len(),
    21→            found: versioned_hashes.len(),
    22→        });
    23→    }
    24→    for (found, expected) in versioned_hashes
    25→        .iter()
    26→        .zip(expected_versioned_hashes.iter())
    27→    {
    28→        if found != expected {
    29→            return Err(Error::VersionHashMismatch {
    30→                expected: *expected,
    31→                found: *found,
    32→            });
    33→        }
    34→    }
    35→
    36→    Ok(())
    37→}
    38→
    39→pub fn extract_versioned_hashes_from_transactions<E: EthSpec>(
    40→    transactions: &types::Transactions<E>,
    41→) -> Result<Vec<VersionedHash>, Error> {
    42→    let mut versioned_hashes = Vec::new();
    43→
    44→    for tx in transactions {
    45→        // TxEnvelope is non-exhaustive so unforunately we can (no longer) write an exhaustive
    46→        // match here.
    47→        if let TxEnvelope::Eip4844(signed_tx_eip4844) = beacon_tx_to_tx_envelope(tx)? {
    48→            versioned_hashes.extend(
    49→                signed_tx_eip4844
    50→                    .tx()
    51→                    .tx()
    52→                    .blob_versioned_hashes
    53→                    .iter()
    54→                    .map(|fb| Hash256::from(fb.0)),
    55→            );
    56→        }
    57→    }
    58→
    59→    Ok(versioned_hashes)
    60→}
    61→
    62→pub fn beacon_tx_to_tx_envelope<N: Unsigned>(
    63→    tx: &types::Transaction<N>,
    64→) -> Result<TxEnvelope, Error> {
    65→    let tx_bytes = Vec::from(tx.clone());
    66→    TxEnvelope::decode(&mut tx_bytes.as_slice())
    67→        .map_err(|e| Error::DecodingTransaction(e.to_string()))
    68→}
