    54→    max_uncompressed_len: usize,
    55→    /// Sets the maximum size we allow for compressed gossipsub message data.
    56→    max_compressed_len: usize,
    57→}
    58→
    59→impl SnappyTransform {
    60→    pub fn new(max_uncompressed_len: usize, max_compressed_len: usize) -> Self {
    61→        SnappyTransform {
    62→            max_uncompressed_len,
    63→            max_compressed_len,
    64→        }
    65→    }
    66→}
