   171→
   172→                // the ssz decoders
   173→                match gossip_topic.kind() {
   174→                    GossipKind::BeaconAggregateAndProof => {
   175→                        let signed_aggregate_and_proof = match fork_context
   176→                            .get_fork_from_context_bytes(gossip_topic.fork_digest)
   177→                        {
   178→                            Some(&fork_name) => {
   179→                                if fork_name.electra_enabled() {
   180→                                    SignedAggregateAndProof::Electra(
   181→                                        SignedAggregateAndProofElectra::from_ssz_bytes(data)
   182→                                            .map_err(|e| format!("{:?}", e))?,
   183→                                    )
   184→                                } else {
   185→                                    SignedAggregateAndProof::Base(
   186→                                        SignedAggregateAndProofBase::from_ssz_bytes(data)
   187→                                            .map_err(|e| format!("{:?}", e))?,
   188→                                    )
   189→                                }
   190→                            }
