    51→/// Used to await the result of executing payload with a remote EE.
    52→pub struct PayloadNotifier<T: BeaconChainTypes> {
    53→    pub chain: Arc<BeaconChain<T>>,
    54→    pub block: Arc<SignedBeaconBlock<T::EthSpec>>,
    55→    payload_verification_status: Option<PayloadVerificationStatus>,
    56→}
    57→
    58→impl<T: BeaconChainTypes> PayloadNotifier<T> {
    59→    pub fn new(
    60→        chain: Arc<BeaconChain<T>>,
    61→        block: Arc<SignedBeaconBlock<T::EthSpec>>,
    62→        state: &BeaconState<T::EthSpec>,
    63→        notify_execution_layer: NotifyExecutionLayer,
    64→    ) -> Result<Self, BlockError> {
    65→        let payload_verification_status = if is_execution_enabled(state, block.message().body()) {
    66→            // Perform the initial stages of payload verification.
    67→            //
    68→            // We will duplicate these checks again during `per_block_processing`, however these
    69→            // checks are cheap and doing them here ensures we have verified them before marking
    70→            // the block as optimistically imported. This is particularly relevant in the case
    71→            // where we do not send the block to the EL at all.
    72→            let block_message = block.message();
    73→            partially_verify_execution_payload::<_, FullPayload<_>>(
    74→                state,
    75→                block.slot(),
    76→                block_message.body(),
    77→                &chain.spec,
    78→            )
    79→            .map_err(BlockError::PerBlockProcessingError)?;
    80→
    81→            match notify_execution_layer {
    82→                NotifyExecutionLayer::No if chain.config.optimistic_finalized_sync => {
    83→                    // Create a NewPayloadRequest (no clones required) and check optimistic sync verifications
    84→                    let new_payload_request: NewPayloadRequest<T::EthSpec> =
    85→                        block_message.try_into()?;
    86→                    if let Err(e) = new_payload_request.perform_optimistic_sync_verifications() {
    87→                        warn!(
    88→                            block_number = ?block_message.execution_payload().map(|payload| payload.block_number()),
    89→                            info = "you can silence this warning with --disable-optimistic-finalized-sync",
    90→                            error = ?e,
    91→                            "Falling back to slow block hash verification"
    92→                        );
    93→                        None
    94→                    } else {
    95→                        Some(PayloadVerificationStatus::Optimistic)
    96→                    }
    97→                }
    98→                _ => None,
    99→            }
   100→        } else {
   101→            Some(PayloadVerificationStatus::Irrelevant)
   102→        };
   103→
   104→        Ok(Self {
   105→            chain,
   106→            block,
   107→            payload_verification_status,
   108→        })
   109→    }
