   111→    pub async fn notify_new_payload(self) -> Result<PayloadVerificationStatus, BlockError> {
   112→        if let Some(precomputed_status) = self.payload_verification_status {
   113→            Ok(precomputed_status)
   114→        } else {
   115→            notify_new_payload(&self.chain, self.block.message()).await
   116→        }
   117→    }
   118→}
