   120→/// Verify that `execution_payload` contained by `block` is considered valid by an execution
   121→/// engine.
   122→///
   123→/// ## Specification
   124→///
   125→/// Equivalent to the `notify_new_payload` function in the merge Beacon Chain Changes, although it
   126→/// contains a few extra checks by running `partially_verify_execution_payload` first:
   127→///
   128→/// https://github.com/ethereum/consensus-specs/blob/v1.1.9/specs/bellatrix/beacon-chain.md#notify_new_payload
   129→async fn notify_new_payload<T: BeaconChainTypes>(
   130→    chain: &Arc<BeaconChain<T>>,
   131→    block: BeaconBlockRef<'_, T::EthSpec>,
   132→) -> Result<PayloadVerificationStatus, BlockError> {
   133→    let execution_layer = chain
   134→        .execution_layer
   135→        .as_ref()
   136→        .ok_or(ExecutionPayloadError::NoExecutionConnection)?;
   137→
   138→    let execution_block_hash = block.execution_payload()?.block_hash();
   139→    let new_payload_response = execution_layer.notify_new_payload(block.try_into()?).await;
   140→
   141→    match new_payload_response {
   142→        Ok(status) => match status {
   143→            PayloadStatus::Valid => Ok(PayloadVerificationStatus::Verified),
   144→            PayloadStatus::Syncing | PayloadStatus::Accepted => {
   145→                Ok(PayloadVerificationStatus::Optimistic)
   146→            }
   147→            PayloadStatus::Invalid {
   148→                latest_valid_hash,
   149→                ref validation_error,
   150→            } => {
   151→                warn!(
   152→                    ?validation_error,
   153→                    ?latest_valid_hash,
   154→                    ?execution_block_hash,
   155→                    root = ?block.tree_hash_root(),
   156→                    graffiti = block.body().graffiti().as_utf8_lossy(),
   157→                    proposer_index = block.proposer_index(),
   158→                    slot = %block.slot(),
   159→                    method = "new_payload",
   160→                    "Invalid execution payload"
   161→                );
   162→
   163→                // Only trigger payload invalidation in fork choice if the
   164→                // `latest_valid_hash` is `Some` and non-zero.
   165→                //
   166→                // A `None` latest valid hash indicates that the EE was unable
   167→                // to determine the most recent valid ancestor. Since `block`
   168→                // has not yet been applied to fork choice, there's nothing to
