   200→/// Processes the block header, returning the proposer index.
   201→pub fn process_block_header<E: EthSpec>(
   202→    state: &mut BeaconState<E>,
   203→    block_header: BeaconBlockHeader,
   204→    verify_block_root: VerifyBlockRoot,
   205→    ctxt: &mut ConsensusContext<E>,
   206→    spec: &ChainSpec,
   207→) -> Result<u64, BlockOperationError<HeaderInvalid>> {
   208→    // Verify that the slots match
   209→    verify!(
   210→        block_header.slot == state.slot(),
   211→        HeaderInvalid::StateSlotMismatch
   212→    );
   213→
   214→    // Verify that the block is newer than the latest block header
   215→    verify!(
   216→        block_header.slot > state.latest_block_header().slot,
   217→        HeaderInvalid::OlderThanLatestBlockHeader {
   218→            block_slot: block_header.slot,
   219→            latest_block_header_slot: state.latest_block_header().slot,
   220→        }
   221→    );
   222→
   223→    // Verify that proposer index is the correct index
   224→    let proposer_index = block_header.proposer_index;
   225→    let state_proposer_index = ctxt.get_proposer_index(state, spec)?;
   226→    verify!(
   227→        proposer_index == state_proposer_index,
   228→        HeaderInvalid::ProposerIndexMismatch {
   229→            block_proposer_index: proposer_index,
   230→            state_proposer_index,
   231→        }
   232→    );
   233→
   234→    if verify_block_root == VerifyBlockRoot::True {
   235→        let expected_previous_block_root = state.latest_block_header().tree_hash_root();
   236→        verify!(
   237→            block_header.parent_root == expected_previous_block_root,
   238→            HeaderInvalid::ParentBlockRootMismatch {
   239→                state: expected_previous_block_root,
   240→                block: block_header.parent_root,
   241→            }
   242→        );
   243→    }
   244→
   245→    state
   246→        .slashings_cache_mut()
   247→        .update_latest_block_slot(block_header.slot);
   248→    *state.latest_block_header_mut() = block_header;
   249→
   250→    // Verify proposer is not slashed
   251→    verify!(
   252→        !state.get_validator(proposer_index as usize)?.slashed,
   253→        HeaderInvalid::ProposerSlashed(proposer_index)
   254→    );
   255→
   256→    Ok(proposer_index)
   257→}
