   259→/// Verifies the signature of a block.
   260→///
   261→/// Spec v0.12.1
   262→pub fn verify_block_signature<E: EthSpec, Payload: AbstractExecPayload<E>>(
   263→    state: &BeaconState<E>,
   264→    block: &SignedBeaconBlock<E, Payload>,
   265→    ctxt: &mut ConsensusContext<E>,
   266→    spec: &ChainSpec,
   267→) -> Result<(), BlockOperationError<HeaderInvalid>> {
   268→    let block_root = Some(ctxt.get_current_block_root(block)?);
   269→    let proposer_index = Some(ctxt.get_proposer_index(state, spec)?);
   270→    verify!(
   271→        block_proposal_signature_set(
   272→            state,
   273→            |i| get_pubkey_from_state(state, i),
   274→            block,
   275→            block_root,
   276→            proposer_index,
   277→            spec
   278→        )?
   279→        .verify(),
   280→        HeaderInvalid::ProposalSignatureInvalid
   281→    );
   282→
   283→    Ok(())
   284→}
   285→
   286→/// Verifies the `randao_reveal` against the block's proposer pubkey and updates
   287→/// `state.latest_randao_mixes`.
   288→pub fn process_randao<E: EthSpec, Payload: AbstractExecPayload<E>>(
   289→    state: &mut BeaconState<E>,
   290→    block: BeaconBlockRef<'_, E, Payload>,
   291→    verify_signatures: VerifySignatures,
